macro_rules! deps {
    () => {
        Unescape!();
        ParseError!();
    };
}

macro_rules! unescape {
    () => {
        deps!();
        # [doc = " Must start with `\\`. Returns the unscaped value as `E` and the number of"] # [doc = " input bytes the escape is long."] # [doc = ""] # [doc = " `unicode` and `byte_escapes` specify which types of escapes are"] # [doc = " supported. [Quote escapes] are always unescaped, [Unicode escapes] only if"] # [doc = " `unicode` is true. If `byte_escapes` is false, [ASCII escapes] are"] # [doc = " used, if it's true, [Byte escapes] are (the only difference being that the"] # [doc = " latter supports \\xHH escapes > 0x7f)."] # [doc = ""] # [doc = " [Quote escapes]: https://doc.rust-lang.org/reference/tokens.html#quote-escapes"] # [doc = " [Unicode escapes]: https://doc.rust-lang.org/reference/tokens.html#unicode-escapes"] # [doc = " [Ascii escapes]: https://doc.rust-lang.org/reference/tokens.html#ascii-escapes"] # [doc = " [Byte escapes]: https://doc.rust-lang.org/reference/tokens.html#byte-escapes"] pub (crate) fn unescape (input : & str , unicode : bool , byte_escapes : bool , allow_nul : bool ,) -> Result < (Unescape , usize) , ParseError > { let first = input . as_bytes () . get (1) . ok_or (perr (0 , UnterminatedEscape)) ? ; let out = match first { b'\'' => (Unescape :: Byte (b'\'') , 2) , b'"' => (Unescape :: Byte (b'"') , 2) , b'n' => (Unescape :: Byte (b'\n') , 2) , b'r' => (Unescape :: Byte (b'\r') , 2) , b't' => (Unescape :: Byte (b'\t') , 2) , b'\\' => (Unescape :: Byte (b'\\') , 2) , b'0' => if allow_nul { (Unescape :: Byte (b'\0') , 2) } else { return Err (perr (0 .. 2 , DisallowedNulEscape)) } , b'x' => { let hex_string = input . get (2 .. 4) . ok_or (perr (0 .. input . len () , UnterminatedEscape)) ? . as_bytes () ; let first = hex_digit_value (hex_string [0]) . ok_or (perr (0 .. 4 , InvalidXEscape)) ? ; let second = hex_digit_value (hex_string [1]) . ok_or (perr (0 .. 4 , InvalidXEscape)) ? ; let value = second + 16 * first ; if ! byte_escapes && value > 0x7F { return Err (perr (0 .. 4 , NonAsciiXEscape)) ; } if ! allow_nul && value == 0 { return Err (perr (0 .. 4 , DisallowedNulEscape)) ; } (Unescape :: Byte (value) , 4) } b'u' => { if ! unicode { return Err (perr (0 .. 2 , UnicodeEscapeInByteLiteral)) ; } if input . as_bytes () . get (2) != Some (& b'{') { return Err (perr (0 .. 2 , UnicodeEscapeWithoutBrace)) ; } let closing_pos = input . bytes () . position (| b | b == b'}') . ok_or (perr (0 .. input . len () , UnterminatedUnicodeEscape)) ? ; let inner = & input [3 .. closing_pos] ; if inner . as_bytes () . first () == Some (& b'_') { return Err (perr (3 , InvalidStartOfUnicodeEscape)) ; } let mut v : u32 = 0 ; let mut digit_count = 0 ; for (i , b) in inner . bytes () . enumerate () { if b == b'_' { continue ; } let digit = hex_digit_value (b) . ok_or (perr (3 + i , NonHexDigitInUnicodeEscape)) ? ; if digit_count == 6 { return Err (perr (3 + i , TooManyDigitInUnicodeEscape)) ; } digit_count += 1 ; v = 16 * v + digit as u32 ; } if ! allow_nul && v == 0 { return Err (perr (0 .. closing_pos + 1 , DisallowedNulEscape)) ; } let c = std :: char :: from_u32 (v) . ok_or (perr (0 .. closing_pos + 1 , InvalidUnicodeEscapeChar)) ? ; (Unescape :: Unicode (c) , closing_pos + 1) } _ => return Err (perr (0 .. 2 , UnknownEscape)) , } ; Ok (out) }
    };
}

unescape!();